function mform(i){const z=i?db.M.find(x=>x.id==i):{date:st.cd||td(),acct:'Cash',amt:'',desc:''},v={...z,klab:KL[KK.indexOf(z.kind)]||KL[0]};
form(i?'Edit entry':'Owner drawings / transfer / other',[['date','Date','date'],['klab','What is it?','select',KL.filter((z,k)=>k!=2&&k!=3)],['amt','Amount (UGX)','number'],['desc','Note','text']],v,r=>{if(!(r.amt>0))return false;r.kind=KK[KL.indexOf(r.klab)];delete r.klab;if(!i)r.acct='Cash';i?Object.assign(z,r):db.M.push({id:id(),...r})},i&&(()=>{db.M=db.M.filter(x=>x.id!=i)}))}
V.help=()=>'<div id="gd"><h2>How to use this system</h2><small>Tap a heading to open it.</small><details><summary>1. First-time setup</summary><ol><li>Go to <b>Setup</b>, enter your shop name, address and phone number (they appear on receipts) and tap <b>Save settings</b>.</li><li>Under <b>Receipt look</b> in Setup you can change the tagline, the about text, the closing message and the logo (or upload your own logo picture).</li><li>Set the <b>Mobile Money charge %</b> if your supplier payments usually cost a known percentage. You can still type the exact fee on each purchase.</li><li>Check your products under <b>Stock</b>. Tap a product to correct its price, <b>opening stock</b>, reorder level, and the usual transport and handling cost per unit.</li><li>If you are starting fresh, use <b>Setup → Clear transactions</b> to remove sample records. Your products stay.</li><li>Take your first backup: <b>Setup → Download backup file</b>.</li></ol></details><details open><summary>2. Your day, step by step</summary><ol><li><b>Morning:</b> open the system. Check <b>Home</b> for items to reorder and money owed to you.</li><li><b>Stock arrives:</b> record it under <b>Money → Purchases</b>.</li><li><b>Every sale:</b> record it on <b>Sell</b>.</li><li><b>Customers paying old debts:</b> <b>Money → Credit</b>.</li><li><b>Spending:</b> record each expense under <b>Money → Expenses</b>.</li><li><b>Evening:</b> count the cash and close the day in <b>Money → Cash book</b>. Then download a backup.</li></ol></details><details><summary>3. Making a sale (one or many products)</summary><ol><li>Tap <b>Sell</b> and search a product. Tap it to add it to the cart. Search and tap again for each extra product.</li><li>Change the <b>quantity</b> (left box) or <b>price</b> (right box) on any line. Tap <b>remove</b> to take a line out.</li><li>Type the customer name (needed for credit) and choose <b>Cash</b>, <b>Mobile Money</b> or <b>Credit</b>.</li><li>Choose <b>Served by</b> (add your staff names in <b>Setup</b> first). The time is recorded automatically when you tap Complete sale, or type another time.</li><li>Tap <b>Complete sale</b>. The receipt opens with the date, time and who served the customer. Tap <b>Print</b> or <b>Share on WhatsApp</b>.</li><li>Printing on a 58mm Bluetooth printer? In <b>Setup → Receipt look</b> set <b>Receipt paper</b> to <b>58mm thermal printer</b>, then tap Print and choose your printer.</li><li>Stock goes down automatically.</li></ol></details><details><summary>4. Customer buys on credit or pays part</summary><ol><li>On <b>Sell</b>, choose <b>Credit</b>. A box appears: <b>Amount paid now</b>. Enter what the customer paid, or leave it empty.</li><li>The receipt shows <b>Paid so far</b> and <b>Balance</b>.</li><li>When they pay more later: <b>Money → Credit</b>, tap the customer, enter the amount and date.</li><li>When the balance reaches zero, the customer leaves the Credit list.</li></ol></details><details><summary>5. Customer advances (pays now, collects later)</summary><ol><li><b>Money → Advances → New advance</b>. Enter the customer, the goods reserved and the amount paid. Set the goods aside.</li><li>When the customer comes, open the advance and tap <b>Customer is collecting goods now</b>. This opens Sell. Add the products and complete the sale. The advance is deducted automatically.</li><li>Advances are held money, not sales, until the customer collects.</li></ol></details><details><summary>6. Recording stock you buy (true cost)</summary><ol><li><b>Money → Purchases → + Record stock arriving</b>.</li><li>Fill in the date, supplier, product, quantity and the <b>unit cost at the supplier</b>. To find the product quickly, type part of its name in the search box above the Product list. The matching products appear and the first one is selected.</li><li>Check <b>Transport per unit</b> and <b>Handling per unit</b>. Fill them in if you pay for transport or handling when stock arrives. The system adds them to the cost of the goods.</li><li>Choose how you paid the supplier. For Mobile Money, enter the <b>mobile money charge</b> (leave 0 to use the Setup %). Use <b>Other costs</b> for errands and packaging, as a total.</li><li>The system adds all these to the cost of the goods. Your profit on every later sale uses this real cost.</li><li>Made a mistake? Tap the purchase in the list to edit or delete it.</li></ol></details><details><summary>7. Buying from a supplier on credit</summary><ol><li>In the purchase form, set <b>Payment to supplier</b> to <b>On credit</b>, type the supplier name, and enter any deposit in <b>Amount paid to supplier now</b>.</li><li>See what you owe under <b>Money → Suppliers</b>.</li><li>To pay: tap the supplier, then <b>Pay supplier</b>. Enter the amount and any Mobile Money charge. Payments settle the oldest purchases first.</li></ol></details><details><summary>8. Expenses</summary><ol><li><b>Money → Expenses → + Add expense</b>. Choose the type, add a description and the amount.</li><li>Record only <b>business</b> costs here (transport, wages, rent, airtime). Do not record stock purchases here, and do not record personal spending here.</li></ol></details><details><summary>9. Daily cash book and closing</summary><ol><li><b>Money → Cash book</b> shows, for the chosen date, the opening balance, all money in (cash and Mobile Money sales, credit payments, advances), all money out (expenses, stock purchases and their transport and charges, supplier payments, owner drawings) and the balance expected.</li><li>Count the cash, tap <b>Close the day</b>, and type the amount counted. The system shows <b>Short by</b> or <b>Over by</b>.</li><li>Tomorrow opens with today\'s counted cash.</li><li>Use <b>+ Owner drawings / transfer / other</b> for: owner drawings, money you put in, and other money in or out.</li></ol></details><details><summary>10. Taking money for personal use</summary><ol><li>Record it as <b>Owner drawings (personal use)</b> in the Cash book. It is not an expense, so your profit stays true.</li><li>Reports shows <b>Owner drawings</b> and <b>Profit after owner drawings</b>. If the second figure is red, you are taking more than the shop earns.</li><li>Take a fixed amount on a fixed day, and count the box before you take it.</li></ol></details><details><summary>11. Stock page</summary><ol><li>Search a product by name. Each line shows price, cost, profit per unit, <b>stock profit</b> (profit on all you hold) and the quantity, marked LOW or CHECK when needed.</li><li>Tap a product to edit it, then <b>View stock history</b> to see the opening stock, every restock and every sale with a running total.</li><li>The top cards show stock value at cost, at selling price, and potential gross profit.</li></ol></details><details><summary>12. Reports: what each card means</summary><ol><li>Use <b>Monthly</b> or <b>Daily report</b> at the top. The daily report shows one day: sales, profit, expenses, stock received, receipts and cash book status. You can print it.</li><li>For the monthly view, pick the month.</li><li><b>Net profit:</b> sales minus cost of goods minus expenses.</li><li><b>Net revenue:</b> sales minus expenses only.</li><li><b>Owner drawings</b> and <b>Profit after owner drawings</b>: what you took out and what the shop kept.</li><li><b>Cash received:</b> money actually collected. <b>Spent on restocking:</b> cash paid for stock. <b>Owed to suppliers:</b> unpaid supplier balances.</li><li><b>Cash left:</b> cash received minus expenses, restocking and drawings.</li><li>Tap a card to open its records. The daily summary and profit by product are further down. Tap a product in <b>Profit by product</b> to see every sale of it, with the date, time, customer and receipt, for the month or for all dates.</li></ol></details><details><summary>13. Backup, restore and Excel</summary><ol><li><b>Setup → Download backup file:</b> do it every evening. Send the file to yourself on WhatsApp.</li><li><b>Setup → Restore from backup:</b> use it on a new phone, after clearing Chrome, or when you install an updated file.</li><li><b>Setup → Download backup as PDF / Share backup PDF:</b> a readable report that also holds a hidden copy of your data. Restore accepts it too.</li><li><b>Setup → Export to Excel:</b> a workbook with sales, products, purchases, expenses, daily summary, product profit, advances, cash book and owner entries.</li><li><b>Setup → Data safety</b> shows whether your records are protected. On Chrome for a computer you can connect an <b>auto-backup file</b> that updates by itself every time you save. The Home page reminds you when no backup was downloaded for 24 hours.</li><li>The app works fully offline. Your records live inside the browser on this device. Do not clear Chrome\'s data without a fresh backup, and keep the file in the same folder.</li></ol></details><details><summary>13b. Share or download sales, stock, receipts and all records (PDF / CSV)</summary><ol><li><b>Sell → Share or download sales &amp; receipts</b> (at the bottom of the Sell page): choose From and To dates, then share or download the sales list and the receipts as a PDF or a CSV file.</li><li><b>Stock → Share or download stock</b>: your full stock list, or only items to reorder, as PDF or CSV.</li><li><b>Reports → Share or download all shop records</b>: the whole business report as PDF, every table as CSV files in one .zip, and a backup file you can restore from.</li><li>Every receipt also has <b>Share receipt as CSV</b> and <b>Download receipt CSV</b> next to the PDF buttons.</li><li><b>Share</b> opens your phone\'s share sheet (WhatsApp, email, Drive). If your device cannot share files, the file is downloaded instead.</li><li>CSV files open in Excel, Google Sheets and any spreadsheet app. They work fully offline.</li><li>To restore a backup: <b>Setup → Restore from backup</b>.</li></ol></details><details><summary>14. Fixing mistakes</summary><ol><li><b>Wrong sale:</b> <b>Sell → Sales history</b>, pick the date, tap the sale, <b>Delete sale</b>. Stock is restored.</li><li><b>Wrong purchase or expense:</b> tap it under <b>Money</b> to edit or delete.</li><li><b>Remove a whole day:</b> <b>Setup → Delete records by date</b>.</li><li><b>Stock looks wrong:</b> open the product and use <b>View stock history</b>. Check the opening stock first.</li></ol></details><details><summary>15. Calculator and shortcuts</summary><ol><li>The round <b>🧮</b> button at the bottom right opens a calculator on any page.</li><li>On <b>Home</b> and <b>Reports</b>, tap a card to jump to its records.</li><li>The <b>?</b> button at the top right brings you back to this guide.</li></ol></details><details><summary>16. Price list for customers</summary><ol><li>Go to <b>Stock → Make price list</b>.</li><li>Type a title and an optional note. Open <b>Choose categories</b> to include only some groups. Tick <b>Only items currently in stock</b> if you want.</li><li>The list below updates as you type. It uses your current selling prices, so change a price on the Stock page and the list follows.</li><li>Tap <b>Print / Save as PDF</b> (choose Save as PDF in the print window to keep a file), <b>Share as text</b> for WhatsApp, or <b>Copy as text</b>.</li></ol></details><details><summary>Customer orders and contacts</summary><ol><li><b>Money → Orders → + New customer order</b>. Enter the customer name, phone number and what they ordered.</li><li>When the goods arrive, open the order and tap <b>Goods have arrived</b>. Home then shows a reminder.</li><li>Tap the customer, then <b>Call</b> or <b>WhatsApp</b> to tell them.</li><li>When they take the goods, tap <b>Customer collected the goods</b>. Then record the sale on <b>Sell</b>.</li></ol></details><details><summary>17. Journal for bits (small amounts sold by money)</summary><ol><li>Go to <b>Money → Journal</b>. Use it when customers buy a small part of a product for a small amount of money, for example a scoop of shea butter or a decant of perfume.</li><li>Tap <b>+ Add money for bits</b>, search the product, and type the amount the customer paid. Keep that money aside. Nothing is taken off stock yet.</li><li>The journal adds up the money for each product and shows how close it is to the price of one unit (for example 7,000 for 1 bottle).</li><li>When a product shows <b>READY</b>, tap it, then <b>Deduct from stock</b>, and confirm the quantity. The app records a cash sale of that quantity, so stock goes down and your reports and cash book include it. Put the kept-aside money into the till on that day.</li><li>If the money kept is more than one unit, the extra stays in the journal for next time.</li><li>To undo a deduction, tap it in the history. The sale it made is removed and the stock comes back.</li></ol></details><details><summary>18. Golden rules</summary><ol><li>Record every sale, purchase and expense on the day it happens.</li><li>Never record a purchase as an expense.</li><li>Count the cash every evening before taking your own money.</li><li>Back up daily, and keep using one device for entering records.</li></ol></details><button class="btn big" onclick="document.querySelectorAll(\'#gd details\').forEach(d=>d.open=true);print()">Print this guide</button><button class="btn" onclick="go(\'home\')">Back to Home</button></div>';
const catList=()=>{const s=[...new Set(db.P.map(p=>p.cat||'Other'))];return s.sort((a,b)=>{const x=db.L.cat.indexOf(a),y=db.L.cat.indexOf(b);return(x<0?99:x)-(y<0?99:y)||(a<b?-1:1)})};
function pitems(){const m=stk(),o=db.PL,g={};db.P.forEach(p=>{const c=p.cat||'Other';if(o.cats.length&&!o.cats.includes(c))return;if(o.instock&&m[p.name]<=0)return;if(!(p.price>0))return;(g[c]=g[c]||[]).push(p)});Object.values(g).forEach(a=>a.sort((x,y)=>x.name<y.name?-1:1));return catList().filter(c=>g[c]).map(c=>[c,g[c]])}
function ptext(){const o=db.PL,L=['*'+db.shop.name+'*',db.shop.addr+(db.shop.tel?' · '+db.shop.tel:''),'*'+o.title+'* – '+td(),''];pitems().forEach(([c,a])=>{L.push('*'+c+'*');a.forEach(p=>L.push(p.name+(p.unit?' ('+p.unit+')':'')+' – '+fm(p.price)));L.push('')});if(o.note)L.push(o.note);return L.join('\n')}
function pvh(){const o=db.PL,G=pitems();return'<div style="text-align:center"><h2>'+esc(db.shop.name)+'</h2><div style="font-size:13px">'+esc(db.shop.addr)+(db.shop.tel?' · '+esc(db.shop.tel):'')+'</div><h3 style="margin-top:8px">'+esc(o.title)+'</h3><div style="font-size:12px;color:#555">Prices in UGX · '+td()+'</div></div><div class="pc" style="margin-top:8px">'+(G.map(([c,a])=>'<div class="pcat"><h4>'+esc(c)+'</h4><table>'+a.map(p=>'<tr><td>'+esc(p.name)+'</td><td>'+esc(p.unit||'')+'</td><td>'+fm(p.price)+'</td></tr>').join('')+'</table></div>').join('')||'<p>No products match your choices.</p>')+'</div>'+(o.note?'<p style="font-size:13px;margin-top:8px"><b>'+esc(o.note)+'</b></p>':'')}
function pset(k,v){db.PL[k]=v;save();$('#pv').innerHTML=pvh()}
function ptog(i){const c=catList()[i],a=db.PL.cats,x=a.indexOf(c);x<0?a.push(c):a.splice(x,1);save();render()}
function pshare(){const x=ptext();if(navigator.share)navigator.share({text:x}).catch(()=>{});else window.open('https://wa.me/?text='+encodeURIComponent(x),'_blank')}
function pcopy(){const x=ptext();(navigator.clipboard?navigator.clipboard.writeText(x):Promise.reject()).then(()=>alert('Price list copied. Paste it into WhatsApp.')).catch(()=>alert('Copy not allowed here. Use Print / Save as PDF instead.'))}
V.price=()=>{const o=db.PL;return'<button class="btn" onclick="go(\'stock\')" style="margin:0 0 6px">← Back to Stock</button><h2>Price list</h2><label>Title</label><input value="'+esc(o.title)+'" oninput="pset(\'title\',this.value)"><label>Note at the bottom (optional)</label><input value="'+esc(o.note)+'" placeholder="e.g. Prices may change without notice" oninput="pset(\'note\',this.value)"><details><summary>Choose categories ('+(o.cats.length||'all')+')</summary>'+catList().map((c,i)=>'<label class="chk"><input type="checkbox" '+(!o.cats.length||o.cats.includes(c)?'checked':'')+' onchange="ptog('+i+')"> '+esc(c)+'</label>').join('')+'<p><small>Nothing ticked = all categories.</small></p></details><label class="chk"><input type="checkbox" '+(o.instock?'checked':'')+' onchange="db.PL.instock=this.checked;save();render()"> Only items currently in stock</label><div id="pv">'+pvh()+'</div><button class="btn big" onclick="print()">Print / Save as PDF</button><button class="btn" onclick="pshare()">Share as text (WhatsApp)</button><button class="btn" onclick="pcopy()">Copy as text</button>'};
function addd(d,n){const x=new Date(d+'T00:00:00Z');x.setUTCDate(x.getUTCDate()+n);return x.toISOString().slice(0,10)}
function drep(){const d=st.rd=st.rd||td(),ss=db.S.filter(s=>s.date==d),x=pl(d),by=p=>sum(ss.filter(s=>s.pay==p),tot),col=sum(db.S.filter(s=>s.pay=='Credit'),s=>sum(s.pays.filter(p=>p.d==d),p=>p.a)),adv=sum(db.A.filter(a=>a.date==d),a=>a.amt),buy=db.U.filter(u=>u.date==d),ex=db.X.filter(z=>z.date==d),dr=sum(db.M.filter(z=>z.kind=='draw'&&z.date==d),z=>z.amt),cb=cbexp(d),cl=db.C.find(z=>z.date==d),it={};
ss.forEach(s=>s.items.forEach(i=>{const r=it[i.n]||(it[i.n]={q:0,s:0,p:0});r.q+=i.q;r.s+=i.q*i.p;r.p+=i.q*(i.p-i.c)}));
const sc=(l,v,c)=>'<div class="stat"><small>'+l+'</small><span class="num '+(c||'')+'">'+fm(v)+'</span></div>',ln=(a,b,c,f)=>'<div class="item" style="cursor:'+(f?'pointer':'default')+'"'+(f?' onclick="'+f+'"':'')+'><span class="nm"><b>'+a+'</b><small>'+b+'</small></span><span class="pr">'+c+'</span></div>';
const rows=Object.entries(it).sort((a,b)=>b[1].p-a[1].p);
return'<div class="seg"><button onclick="st.rd=addd(\''+d+'\',-1);render()">← Previous</button><button onclick="st.rd=td();render()">Today</button><button onclick="st.rd=addd(\''+d+'\',1);render()">Next →</button></div><input type="date" value="'+d+'" onchange="st.rd=this.value||td();render()"><div id="gd"><div style="text-align:center;margin-bottom:8px"><b style="font-size:18px">'+esc(db.shop.name)+'</b><br><small>'+esc(db.shop.addr)+'</small><br><b>DAILY REPORT · '+d+'</b></div><div class="cards"><div class="stat wide"><small>Total sales ('+x.n+' receipts)</small><span class="num">UGX '+fm(x.t)+'</span></div>'+sc('Cash sales',by('Cash'))+sc('Mobile Money sales',by('Mobile Money'))+sc('Credit sales',by('Credit'))+sc('Credit payments received',col)+sc('Advances received',adv)+sc('Gross profit',x.g)+sc('Expenses',x.e)+'<div class="stat wide"><small>Net profit for the day</small><span class="num '+(x.net<0?'low':'ok')+'">UGX '+fm(x.net)+'</span></div>'+sc('Stock bought (full cost)',sum(buy,u=>u.q*ul(u)))+sc('Cash paid for stock',sum(db.U,u=>cashOut(u,d)))+sc('Owner drawings',dr)+'</div><h3>Products sold</h3>'+(rows.length?'<div class="tw"><table><tr><th>Product</th><th>Qty</th><th>Sales</th><th>Profit</th></tr>'+rows.map(([n,r])=>'<tr><td>'+esc(n)+'</td><td>'+r.q+'</td><td>'+fm(r.s)+'</td><td>'+fm(r.p)+'</td></tr>').join('')+'</table></div>':'<div class="empty">No sales on this day</div>')+'<h3>Receipts</h3>'+ss.map(s=>ln('#'+s.no+' '+esc(s.cust||'Walk-in'),s.items.map(i=>esc(i.n)+' ×'+i.q).join(', ')+' · '+s.pay+(s.time?' · '+s.time:'')+(s.by?' · '+esc(s.by):''),fm(tot(s)),'rcpt('+s.id+')')).join('')+'<h3>Sales by person who served</h3>'+(()=>{const m={};ss.forEach(s=>{const k=s.by||'(not recorded)';m[k]=(m[k]||0)+tot(s)});return Object.entries(m).map(([k,v])=>ln(esc(k),'',fm(v))).join('')})()+'<h3>Expenses</h3>'+(ex.map(z=>ln(esc(z.desc||z.type),esc(z.type),fm(z.amt))).join('')||'<small>None</small>')+'<h3>Stock received</h3>'+(buy.map(u=>ln(esc(u.n),u.q+' @ '+fm(ul(u))+' · '+esc(u.sup||''),fm(u.q*ul(u)))).join('')||'<small>None</small>')+'<h3>Cash book</h3>'+(cl?ln(cl.cc-cb.c==0?'Closed · Balanced':(cl.cc<cb.c?'Closed · Short by ':'Closed · Over by ')+fm(Math.abs(cl.cc-cb.c)),'Counted cash '+fm(cl.cc)+' · expected '+fm(cb.c),fm(cl.cc)):ln('Not closed yet','Expected cash in the box: '+fm(cb.c),fm(cb.c))+'<button class="btn np" onclick="st.cd=\''+d+'\';nav(\'money\',\'cb\')">Go to Cash book</button>')+'</div><button class="btn big np" onclick="print()">Print daily report</button><button class="btn np" onclick="X.dayReport(1)">📄 Share daily report as PDF</button><button class="btn np" onclick="X.dayReport(0)">⬇ Download daily report PDF</button>'}
function plist(){const q=st.q.toLowerCase(),m=stk(),el=$('#pl');if(!el)return;
el.innerHTML=db.P.filter(p=>p.name.toLowerCase().includes(q)).slice(0,q?20:6).map(p=>'<button class="item" onclick="add('+p.id+')"><span class="nm"><b>'+esc(p.name)+'</b><small>'+m[p.name]+' '+p.unit+' in stock</small></span><span class="pr">'+fm(p.price)+'</span></button>').join('')}
function add(i){const p=db.P.find(x=>x.id==i),l=st.cart.find(x=>x.n==p.name);if(l)l.q++;else st.cart.push({n:p.name,q:1,p:p.price,c:costNow(p)});st.q='';render()}
function pmc(e){$('#pnw').classList.toggle('hide',e.value!='Credit')}
const nowt=()=>{const d=new Date();return String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0')};
function sbx(){const L=db.staff||[];return '<label>Served by</label>'+(L.length?'<select id="sb"><option value="">(not recorded)</option>'+L.map(n=>'<option'+(n==db.lastSb?' selected':'')+'>'+esc(n)+'</option>').join('')+'</select>':'<input id="sb" placeholder="Name of the person serving (optional)" value="'+esc(db.lastSb||'')+'">')}
function done(){const cu=$('#cu').value.trim(),pay=$('#pm').value;if(pay=='Credit'&&!cu)return alert('Enter the customer name for a credit sale.');
if(st.cart.some(i=>!(i.q>0)))return alert('Check quantities.');const T=sum(st.cart,i=>i.q*i.p),a=st.adv&&db.A.find(x=>x.id==st.adv),ap=a?Math.min(abal(a),T):0,pn=pay=='Credit'?+($('#pn')?.value)||0:0;if(pn<0||pn>T-ap)return alert('Amount paid now must be between 0 and '+fm(T-ap)+'.');
const s={id:id(),no:Math.max(0,...db.S.map(x=>+x.no||0))+1,date:$('#sd').value||td(),time:$('#stm').value||nowt(),by:($('#sb')?.value||'').trim(),cust:cu,pay,pays:[],items:st.cart.map(i=>({...i}))};if(pn>0)s.pays.push({d:s.date,a:pn});if(ap>0){s.advId=a.id;s.advA=ap}db.lastSb=s.by;st.adv=null;db.S.push(s);st.cart=[];save();render();rcpt(s.id);toast('Sale saved ✓')}
/* ---- logos drawn in code (no picture files needed) ---- */
const xe=s=>String(s==null?'':s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const rootCss=n=>{try{return getComputedStyle(document.documentElement).getPropertyValue(n).trim()}catch(e){return''}};
