function ev(s){s=s.replace(/[+\-*/.]+$/,'').replace(/(^|[^\d.])0+(?=\d)/g,'$1');if(!s||!/^[0-9+\-*/. ]+$/.test(s))return null;try{const v=Function('return '+s)();return isFinite(v)?Math.round(v*1e8)/1e8:null}catch(e){return null}}
function calc(){cx='';const K=['C','⌫','%','÷','7','8','9','×','4','5','6','−','1','2','3','+','0','.','00','='];
modal('<h2>Calculator</h2><div class="stat wide" style="text-align:right"><small id="ce" style="min-height:1.3em;display:block;overflow-wrap:anywhere"></small><span class="num" id="cr" style="font-size:30px">0</span></div><div class="kp">'+K.map(k=>'<button class="'+('÷×−+='.includes(k)?'op':k=='C'||k=='⌫'?'fn':'')+'" onclick="kp(\''+k+'\')">'+k+'</button>').join('')+'</div><button class="btn" onclick="modal()">Close</button>')}
function kp(k){const op=/[+\-*/]$/;
if(k=='C')cx='';else if(k=='⌫')cx=cx.slice(0,-1);
else if(k=='=')cx=String(ev(cx)??cx);
else if(k=='%')cx=cx.replace(/(\d+\.?\d*)$/,m=>String(+m/100));
else{const c={'÷':'/','×':'*','−':'-'}[k]||k;if('+-*/'.includes(c)){if(!cx&&c!='-')return;if(op.test(cx))cx=cx.slice(0,-1)}if(c=='.'&&/\.\d*$/.test(cx))return;cx+=c}
const r=ev(cx);$('#ce').textContent=cx.replace(/\//g,'÷').replace(/\*/g,'×').replace(/-/g,'−');$('#cr').textContent=r==null?'0':r.toLocaleString('en-US',{maximumFractionDigits:8})}
